package vip.xiaonuo.srm.quality;
import java.util.*;import java.time.*;import java.math.*;import com.fasterxml.jackson.databind.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.jdbc.core.JdbcTemplate;import vip.xiaonuo.srm.api.*;import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;import vip.xiaonuo.common.exception.CommonException;
@Component @RequiredArgsConstructor public class QualityStore {
 final JdbcTemplate db;final SrmSupplierAccessApi access;final SrmDataProtectionApi crypto;final SrmBusinessFileApi files;final ObjectMapper mapper;final jakarta.validation.Validator validator;
 static String id(){return cn.hutool.core.util.IdUtil.getSnowflakeNextIdStr();}static String s(Map<String,Object> r,String k){return r.get(k)==null?"":String.valueOf(r.get(k));}static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}static void require(boolean yes,int code,String msg){if(!yes)throw new CommonException(code,msg);}
 String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new CommonException(400,"质量数据格式无效");}}Map<String,Object> object(String v){try{return mapper.readValue(v,LinkedHashMap.class);}catch(Exception e){throw new CommonException(400,"质量数据格式无效");}}String hash(Object v){try{return cn.hutool.crypto.digest.DigestUtil.sha256Hex(mapper.copy().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true).writeValueAsString(v));}catch(Exception e){throw new CommonException(400,"质量数据无效");}}
 <T>T input(Object v,Class<T> t){try{T p=mapper.convertValue(v,t);require(validator.validate(p).isEmpty(),400,"质量来源字段或精度无效");return p;}catch(CommonException e){throw e;}catch(Exception e){throw new CommonException(400,"质量来源数据无效");}}
 boolean has(Context a,String...roles){return !Collections.disjoint(a.roles(),Set.of(roles));}void readable(Context a){require(a.portal()?has(a,"QUALITY","ADMIN"):has(a,"SQE","CAT-MGR","superAdmin"),403,"当前角色无质量风险权限");}void supplierWriter(Context a){require(a.portal()&&has(a,"QUALITY","ADMIN"),403,"仅本供方质量人员可提交");}void sqe(Context a){require(!a.portal()&&has(a,"SQE","superAdmin"),403,"仅SQE可审核质量业务");}void manager(Context a){require(!a.portal()&&has(a,"CAT-MGR","superAdmin"),403,"仅采购经理可处置");}
 Map<String,Object> row(Context a,String table,String id,boolean lock){readable(a);var rows=db.queryForList("SELECT * FROM "+table+" WHERE ID=?",id);require(rows.size()==1,404,"记录不存在或无权访问");var r=rows.get(0);access.requireSupplier(a,s(r,"SUPPLIER_ID"),lock);boolean scope=a.portal()?a.orgId().equals(s(r,"ORG_ID"))&&a.supplierId().equals(s(r,"SUPPLIER_ID")):a.allOrganizations()||a.ownOnly()&&a.orgId().equals(s(r,"ORG_ID"))&&a.userId().equals(s(r,"CREATED_BY"))||!a.ownOnly()&&a.organizationIds().contains(s(r,"ORG_ID"));require(scope,404,"记录不存在或无权访问");return lock?db.queryForMap("SELECT * FROM "+table+" WHERE ID=? FOR UPDATE",id):r;}
 String where(Context a,List<Object> args,String alias){readable(a);String p=alias+".";if(a.portal()){args.add(a.orgId());args.add(a.supplierId());return p+"ORG_ID=? AND "+p+"SUPPLIER_ID=?";}if(a.allOrganizations())return "1=1";if(a.ownOnly()){args.add(a.orgId());args.add(a.userId());return p+"ORG_ID=? AND "+p+"CREATED_BY=?";}if(a.organizationIds().isEmpty())return "1=0";args.addAll(a.organizationIds());return p+"ORG_ID IN ("+String.join(",",Collections.nCopies(a.organizationIds().size(),"?"))+")";}
 void version(Map<String,Object> r,long v){require(n(r,"ROW_VERSION")==v,409,"记录已变化，请刷新");}Context system(String org,String actor){return new Context(actor,org,null,Set.of("SQE","CAT-MGR","SYSTEM"),false,Set.of(org),false,false);}
 Map<String,Object> policy(String org){var rs=db.queryForList("SELECT VERSION,CONFIG FROM SRM_QL_POLICY WHERE ORG_ID=? ORDER BY VERSION DESC LIMIT 1",org);return rs.isEmpty()?new LinkedHashMap<>(Map.of("version",0L,"responseDays",14,"repeatWindowDays",90,"minorDeduction",5,"majorDeduction",10,"severeDeduction",20)):withVersion(rs.get(0));}Map<String,Object> withVersion(Map<String,Object> r){var c=object(s(r,"CONFIG"));c.put("version",r.get("VERSION"));return c;}
 void action(Context a,String id,String action,Object content){db.update("INSERT INTO SRM_QL_ACTION VALUES(?,?,?,?,?,NOW(3))",id(),id,action,a.userId(),crypto.encrypt(json(content)));}void audit(Context a,Map<String,Object> r,String action){access.recordEvent(a,s(r,"SUPPLIER_ID"),s(r,"ID"),action,Map.of("rowVersion",n(r,"ROW_VERSION")));}
 void notice(Map<String,Object> r,String message,String key,boolean portal){for(String audience:portal?List.of("SQE","PORTAL"):List.of("SQE"))db.update("INSERT IGNORE INTO SRM_QL_NOTICE VALUES(?,?,?,?,?,?,?,?,NOW(3))",id(),r.get("ORG_ID"),r.get("SUPPLIER_ID"),r.get("CREATED_BY"),audience,r.get("ID"),message,key);}
 void event(Context a,String sid,String type,String key,String origin,Object basis){if(key.length()>128)key=key.substring(0,32)+":"+hash(key);var supplier=access.requireSupplier(a,sid,true);db.update("INSERT IGNORE INTO SRM_QL_RISK(ID,ORG_ID,SUPPLIER_ID,RISK_TYPE,EVENT_KEY,SOURCE,ORIGIN_KIND,BASIS_CIPHER,STATUS,CREATED_BY,CREATED_AT,UPDATED_AT) VALUES(?,?,?,?,?,'INTERNAL',?,?,'PENDING',?,NOW(3),NOW(3))",id(),supplier.orgId(),sid,type,key,origin,crypto.encrypt(json(basis)),a.userId());var r=db.queryForMap("SELECT * FROM SRM_QL_RISK WHERE EVENT_KEY=?",key);notice(r,"新增内部风险事件，请评估："+type,"risk:"+r.get("ID"),false);}
}
